(()=>{const A='#ff86c2',reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`body{background:radial-gradient(circle at 50% 0,#171a35 0,#090b18 48%,#05060c 100%);transition:background 1.5s ease}body:has(.writing){}body:before{content:'';position:fixed;inset:0;pointer-events:none;z-index:-2;background:radial-gradient(circle at 20% 25%,#7285c510,transparent 30%),radial-gradient(circle at 80% 70%,#ff86c208,transparent 35%)}.fxbar{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fxbar i{display:block;height:100%;width:0;background:${A};box-shadow:0 0 15px ${A}}.fx-orb{position:fixed;border-radius:50%;pointer-events:none;filter:blur(90px);opacity:.12;z-index:-1}.fx-orb.a{width:420px;height:420px;left:-160px;top:8%;background:#344b88;animation:drift 16s ease-in-out infinite}.fx-orb.b{width:380px;height:380px;right:-160px;bottom:4%;background:#ff86c2;animation:drift 20s ease-in-out infinite reverse}.fx-ink{position:fixed;pointer-events:none;z-index:2;width:7px;height:7px;border-radius:50%;background:#302438;box-shadow:0 0 10px #ff86c244;opacity:0;animation:ink 7s ease-in-out infinite}.fx-heart{position:fixed;pointer-events:none;z-index:2;color:${A};opacity:0;animation:heart 9s ease-out infinite}.fxr{opacity:0;transform:translateY(38px) scale(.985);transition:1s cubic-bezier(.2,.8,.2,1)}.fxr.on{opacity:1;transform:none}.writing:after{content:'|';animation:cursor .8s steps(1) infinite;color:${A}}.photo-slot.focused{transform:scale(1.025) rotate(-1deg);box-shadow:0 30px 90px #ff4f9d22}.answer-pop{animation:answer .7s ease}@keyframes drift{50%{transform:translate(80px,-45px)}}@keyframes ink{0%,100%{transform:translate(0,20px) scale(.4);opacity:0}25%{opacity:.3}55%{transform:translate(25px,-70px) scale(1);opacity:.12}}@keyframes heart{0%{transform:translateY(18vh) rotate(-10deg);opacity:0}18%{opacity:.45}100%{transform:translateY(-105vh) translateX(35px) rotate(35deg);opacity:0}}@keyframes cursor{50%{opacity:0}}@keyframes answer{50%{transform:scale(1.06)}}`;b.appendChild(s);const bar=document.createElement('div');bar.className='fxbar';bar.innerHTML='<i></i>';b.appendChild(bar);['a','b'].forEach(c=>{const o=document.createElement('div');o.className='fx-orb '+c;b.appendChild(o)});if(!reduce){for(let i=0;i<28;i++){const p=document.createElement('i');p.className='fx-ink';p.style.left=Math.random()*100+'%';p.style.top=15+Math.random()*80+'%';p.style.animationDelay=-Math.random()*7+'s';p.style.animationDuration=5+Math.random()*5+'s';b.appendChild(p)}for(let i=0;i<14;i++){const h=document.createElement('span');h.className='fx-heart';h.textContent=['♡','♥','✦'][i%3];h.style.left=Math.random()*100+'%';h.style.fontSize=11+Math.random()*16+'px';h.style.animationDelay=-Math.random()*9+'s';b.appendChild(h)}}document.querySelectorAll('section').forEach(e=>e.classList.add('fxr'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fxr').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.firstElementChild.style.width=(m?scrollY/m*100:0)+'%'})})();